// Native gcrv type 2: Hermite keys (normalized time, value, incoming/outgoing tangent).
function rareCurve(channel,t){const keys=channel.keys;let i=1;while(i<keys.length-1&&keys[i][0]<t)i++;const a=keys[i-1],b=keys[i],width=b[0]-a[0],u=(t-a[0])/width,u2=u*u,u3=u2*u;return channel.amplitude*((2*u3-3*u2+1)*a[1]+(u3-2*u2+u)*width*a[3]+(-2*u3+3*u2)*b[1]+(u3-u2)*width*b[2]);}
